B=[
('الْحَمَّالُ وَالتَّاجِرُ','Hamal ve tüccar',[
('فِي مَدِينَةِ بَغْدَادَ كَانَ يَعِيشُ رَجُلٌ فَقِيرٌ اسْمُهُ السِّنْدِبَادُ الْحَمَّالُ.','Bağdat şehrinde Hamal Sindbad adında fakir bir adam yaşıyordu.'),
('كَانَ يَحْمِلُ الْأَشْيَاءَ الثَّقِيلَةَ عَلَى رَأْسِهِ فِي السُّوقِ.','Çarşıda ağır eşyaları başının üstünde taşırdı.'),
('وَفِي يَوْمٍ حَارٍّ تَعِبَ كَثِيرًا، فَجَلَسَ أَمَامَ بَيْتٍ كَبِيرٍ.','Sıcak bir günde çok yoruldu ve büyük bir evin önüne oturdu.'),
('كَانَ الْبَيْتُ جَمِيلًا، وَفِيهِ حَدِيقَةٌ وَمَاءٌ بَارِدٌ.','Ev güzeldi; içinde bir bahçe ve soğuk su vardı.'),
('سَمِعَ الْحَمَّالُ صَوْتَ الْغِنَاءِ، وَشَمَّ رَائِحَةَ الطَّعَامِ.','Hamal şarkı sesini duydu ve yemek kokusunu aldı.'),
('فَقَالَ فِي نَفْسِهِ: «يَا رَبِّ، صَاحِبُ هَذَا الْبَيْتِ غَنِيٌّ، وَأَنَا فَقِيرٌ.»','İçinden dedi ki: “Ya Rabbi, bu evin sahibi zengin, bense fakirim.”'),
('«هُوَ يَأْكُلُ وَيَشْرَبُ، وَأَنَا أَحْمِلُ وَأَتْعَبُ.»','“O yiyor ve içiyor, ben ise taşıyor ve yoruluyorum.”'),
('فَخَرَجَ خَادِمٌ صَغِيرٌ مِنَ الْبَيْتِ وَقَالَ: «سَيِّدِي يَدْعُوكَ.»','Evden küçük bir hizmetçi çıktı ve “Efendim seni çağırıyor” dedi.'),
('دَخَلَ الْحَمَّالُ الْبَيْتَ وَهُوَ خَائِفٌ قَلِيلًا.','Hamal biraz korkarak eve girdi.'),
('رَأَى رَجُلًا كَبِيرًا فِي السِّنِّ، وَجْهُهُ طَيِّبٌ وَلِحْيَتُهُ بَيْضَاءُ.','Yaşlı, yüzü iyi huylu ve sakalı beyaz bir adam gördü.')]),
('سِنْدِبَادُ الْبَحْرِيُّ','Denizci Sindbad',[
('قَالَ الرَّجُلُ: «أَهْلًا وَسَهْلًا. مَا اسْمُكَ؟»','Adam “Hoş geldin. Adın ne?” dedi.'),
('قَالَ الْحَمَّالُ: «اسْمِي السِّنْدِبَادُ الْحَمَّالُ.»','Hamal “Adım Hamal Sindbad” dedi.'),
('ضَحِكَ الرَّجُلُ وَقَالَ: «وَأَنَا اسْمِي السِّنْدِبَادُ أَيْضًا، السِّنْدِبَادُ الْبَحْرِيُّ!»','Adam güldü ve “Benim adım da Sindbad; Denizci Sindbad!” dedi.'),
('«سَمِعْتُ كَلَامَكَ أَمَامَ الْبَيْتِ. أَنْتَ تَظُنُّ أَنَّ الْمَالَ جَاءَنِي بِسُهُولَةٍ.»','“Evin önündeki sözlerini duydum. Malın bana kolayca geldiğini sanıyorsun.”'),
('«لَا يَا أَخِي، أَنَا سَافَرْتُ سَبْعَ رِحْلَاتٍ فِي الْبَحْرِ.»','“Hayır kardeşim, ben denizde yedi yolculuk yaptım.”'),
('«وَفِي كُلِّ رِحْلَةٍ رَأَيْتُ الْخَوْفَ وَالْجُوعَ وَالْمَوْتَ.»','“Ve her yolculukta korkuyu, açlığı ve ölümü gördüm.”'),
('«اجْلِسْ وَكُلْ مَعَنَا، ثُمَّ اسْمَعْ قِصَّتِي.»','“Otur, bizimle ye, sonra hikâyemi dinle.”'),
('أَكَلَ الْحَمَّالُ حَتَّى شَبِعَ، وَشَرِبَ الْمَاءَ الْبَارِدَ.','Hamal doyana kadar yedi ve soğuk suyu içti.'),
('ثُمَّ بَدَأَ السِّنْدِبَادُ الْبَحْرِيُّ يَحْكِي.','Sonra Denizci Sindbad anlatmaya başladı.')]),
('الرِّحْلَةُ الْأُولَى: الشَّابُّ الْمُسْرِفُ','Birinci yolculuk: Savurgan genç',[
('«كَانَ أَبِي تَاجِرًا غَنِيًّا، وَمَاتَ وَأَنَا صَغِيرٌ.»','“Babam zengin bir tüccardı; ben küçükken öldü.”'),
('«تَرَكَ لِي مَالًا كَثِيرًا، وَبُيُوتًا وَأَرْضًا.»','“Bana çok mal, evler ve toprak bıraktı.”'),
('«وَلَمَّا كَبِرْتُ، أَكَلْتُ وَشَرِبْتُ وَلَبِسْتُ أَجْمَلَ الثِّيَابِ.»','“Büyüyünce yiyip içtim ve en güzel elbiseleri giydim.”'),
('«وَكَانَ لِي أَصْحَابٌ كَثِيرُونَ، يَأْكُلُونَ مِنْ مَالِي.»','“Malımdan yiyen pek çok arkadaşım vardı.”'),
('«وَفِي يَوْمٍ نَظَرْتُ فَوَجَدْتُ أَنَّ مَالِي قَلَّ كَثِيرًا.»','“Bir gün baktım ve malımın çok azaldığını gördüm.”'),
('«فَخِفْتُ مِنَ الْفَقْرِ، وَتَذَكَّرْتُ كَلَامَ أَبِي: الْمَالُ يَذْهَبُ إِذَا لَمْ تَعْمَلْ.»','“Fakirlikten korktum ve babamın sözünü hatırladım: Çalışmazsan mal gider.”'),
('«فَبِعْتُ مَا بَقِيَ مِنْ أَرْضِي، وَاشْتَرَيْتُ بِضَاعَةً.»','“Toprağımdan kalanı sattım ve ticaret malı aldım.”'),
('«وَقُلْتُ: سَأُسَافِرُ وَأَعْمَلُ مِثْلَ أَبِي.»','“Ve dedim ki: Babam gibi yolculuk edip çalışacağım.”')]),
('إِلَى الْبَصْرَةِ','Basra’ya',[
('«ذَهَبْتُ مِنْ بَغْدَادَ إِلَى الْبَصْرَةِ فِي قَارِبٍ عَلَى النَّهْرِ.»','“Bağdat’tan Basra’ya nehirde bir kayıkla gittim.”'),
('«الْبَصْرَةُ مَدِينَةٌ عَلَى الْبَحْرِ، فِيهَا سُفُنٌ كَثِيرَةٌ.»','“Basra deniz kenarında bir şehirdir; orada çok gemi vardır.”'),
('«رَكِبْتُ سَفِينَةً كَبِيرَةً مَعَ تُجَّارٍ طَيِّبِينَ.»','“İyi tüccarlarla büyük bir gemiye bindim.”'),
('«كَانَ الْقُبْطَانُ رَجُلًا قَوِيًّا، يَعْرِفُ الْبَحْرَ جَيِّدًا.»','“Kaptan güçlü bir adamdı, denizi iyi bilirdi.”'),
('«سَافَرْنَا أَيَّامًا كَثِيرَةً، وَزُرْنَا جُزُرًا وَمُدُنًا.»','“Uzun günler yol aldık; adaları ve şehirleri ziyaret ettik.”'),
('«وَفِي كُلِّ مَدِينَةٍ كُنَّا نَبِيعُ وَنَشْتَرِي.»','“Her şehirde alıp satardık.”'),
('«كَانَ الْبَحْرُ هَادِئًا، وَالْهَوَاءُ طَيِّبًا، وَكُنْتُ سَعِيدًا.»','“Deniz sakin, hava güzeldi ve ben mutluydum.”')]),
('الْجَزِيرَةُ الَّتِي تَتَحَرَّكُ','Hareket eden ada',[
('«وَفِي يَوْمٍ رَأَيْنَا جَزِيرَةً صَغِيرَةً خَضْرَاءَ، كَأَنَّهَا حَدِيقَةٌ.»','“Bir gün bahçe gibi, küçük, yeşil bir ada gördük.”'),
('«قَالَ الْقُبْطَانُ: انْزِلُوا وَاسْتَرِيحُوا قَلِيلًا.»','“Kaptan dedi ki: İnin ve biraz dinlenin.”'),
('«نَزَلْنَا، فَمَشَى بَعْضُنَا، وَصَلَّى بَعْضُنَا، وَأَشْعَلَ بَعْضُنَا نَارًا لِلطَّبْخِ.»','“İndik; kimimiz yürüdü, kimimiz namaz kıldı, kimimiz yemek için ateş yaktı.”'),
('«فَجْأَةً اهْتَزَّتِ الْأَرْضُ تَحْتَ أَقْدَامِنَا!»','“Birden ayaklarımızın altındaki yer sarsıldı!”'),
('«صَاحَ الْقُبْطَانُ مِنَ السَّفِينَةِ: ارْجِعُوا! ارْجِعُوا بِسُرْعَةٍ!»','“Kaptan gemiden bağırdı: Dönün! Çabuk dönün!”'),
('«هَذِهِ لَيْسَتْ جَزِيرَةً، هَذَا حُوتٌ عَظِيمٌ نَامَ فِي الْبَحْرِ زَمَنًا طَوِيلًا!»','“Bu bir ada değil; bu, denizde uzun zaman uyumuş dev bir balina!”'),
('«أَحَسَّ الْحُوتُ بِحَرَارَةِ النَّارِ، فَتَحَرَّكَ وَنَزَلَ فِي الْمَاءِ.»','“Balina ateşin sıcaklığını hissetti, kıpırdadı ve suya daldı.”'),
('«رَكَضَ النَّاسُ إِلَى السَّفِينَةِ، وَبَعْضُهُمْ سَقَطَ فِي الْبَحْرِ.»','“İnsanlar gemiye koştu; bazıları denize düştü.”'),
('«وَكُنْتُ أَنَا مِنَ الَّذِينَ سَقَطُوا.»','“Ben de düşenlerdendim.”')]),
('وَحْدِي فِي الْبَحْرِ','Denizde yalnız',[
('«نَظَرْتُ حَوْلِي، فَرَأَيْتُ السَّفِينَةَ تَبْتَعِدُ.»','“Etrafıma baktım ve geminin uzaklaştığını gördüm.”'),
('«صِحْتُ بِأَعْلَى صَوْتِي، لَكِنْ لَمْ يَسْمَعْنِي أَحَدٌ.»','“Bütün gücümle bağırdım, ama kimse beni duymadı.”'),
('«وَجَدْتُ قِطْعَةَ خَشَبٍ كَبِيرَةً، فَأَمْسَكْتُهَا بِيَدَيَّ.»','“Büyük bir tahta parçası buldum ve onu iki elimle tuttum.”'),
('«بَقِيتُ فِي الْمَاءِ يَوْمًا وَلَيْلَةً، وَالْأَمْوَاجُ تَرْفَعُنِي وَتُنْزِلُنِي.»','“Bir gün bir gece suda kaldım; dalgalar beni kaldırıp indiriyordu.”'),
('«كُنْتُ جَائِعًا وَعَطْشَانَ وَخَائِفًا.»','“Aç, susuz ve korkmuştum.”'),
('«فَدَعَوْتُ اللهَ وَقُلْتُ: يَا رَبِّ، نَجِّنِي.»','“Allah’a dua edip dedim ki: Ya Rabbi, beni kurtar.”'),
('«وَفِي الصَّبَاحِ رَأَيْتُ أَرْضًا بَعِيدَةً، فِيهَا أَشْجَارٌ عَالِيَةٌ.»','“Sabah uzakta, yüksek ağaçları olan bir kara gördüm.”'),
('«حَمَلَتْنِي الْأَمْوَاجُ إِلَيْهَا، فَوَصَلْتُ إِلَى الشَّاطِئِ وَنِمْتُ مِنَ التَّعَبِ.»','“Dalgalar beni oraya taşıdı; kıyıya vardım ve yorgunluktan uyudum.”')]),
('الْفَرَسُ وَالسَّائِسُ','At ve seyis',[
('«لَمَّا اسْتَيْقَظْتُ، أَكَلْتُ مِنَ الْفَوَاكِهِ وَشَرِبْتُ مِنْ عَيْنِ مَاءٍ.»','“Uyanınca meyvelerden yedim ve bir pınardan su içtim.”'),
('«ثُمَّ مَشَيْتُ فِي الْجَزِيرَةِ أَبْحَثُ عَنْ إِنْسَانٍ.»','“Sonra bir insan arayarak adada yürüdüm.”'),
('«فَرَأَيْتُ فَرَسًا جَمِيلَةً مَرْبُوطَةً عِنْدَ الشَّاطِئِ.»','“Kıyıda bağlı güzel bir kısrak gördüm.”'),
('«وَخَرَجَ رَجُلٌ مِنْ تَحْتِ الْأَرْضِ وَقَالَ: مَنْ أَنْتَ؟»','“Yerin altından bir adam çıktı ve dedi ki: Sen kimsin?”'),
('«حَكَيْتُ لَهُ قِصَّتِي، فَأَخَذَنِي إِلَى مَكَانِهِ وَأَطْعَمَنِي.»','“Ona hikâyemi anlattım; beni yerine götürdü ve doyurdu.”'),
('«قَالَ: نَحْنُ سُيَّاسُ الْمَلِكِ مِهْرَجَانَ، نَرْعَى خَيْلَهُ.»','“Dedi ki: Biz Kral Mihrican’ın seyisleriyiz, atlarına bakarız.”'),
('«وَغَدًا نَرْجِعُ إِلَى الْمَدِينَةِ، فَتَعَالَ مَعَنَا.»','“Yarın şehre dönüyoruz; sen de bizimle gel.”')]),
('عِنْدَ الْمَلِكِ مِهْرَجَانَ','Kral Mihrican’ın yanında',[
('«ذَهَبْتُ مَعَهُمْ إِلَى الْمَلِكِ، فَسَأَلَنِي عَنْ بَلَدِي.»','“Onlarla krala gittim; bana memleketimi sordu.”'),
('«قُلْتُ: أَنَا مِنْ بَغْدَادَ، مَدِينَةِ السَّلَامِ.»','“Dedim ki: Ben Bağdat’tanım, Dârüsselâm şehrinden.”'),
('«فَأَكْرَمَنِي الْمَلِكُ، وَجَعَلَنِي كَاتِبًا عَلَى الْمِينَاءِ.»','“Kral bana ikram etti ve beni limana kâtip yaptı.”'),
('«كُنْتُ أَكْتُبُ أَسْمَاءَ السُّفُنِ وَالْبَضَائِعِ كُلَّ يَوْمٍ.»','“Her gün gemilerin ve malların adlarını yazardım.”'),
('«وَكُنْتُ أَسْأَلُ كُلَّ تَاجِرٍ: هَلْ تَعْرِفُ طَرِيقَ بَغْدَادَ؟»','“Her tüccara sorardım: Bağdat’ın yolunu biliyor musun?”'),
('«فَيَقُولُونَ: لَا، بَغْدَادُ بَعِيدَةٌ جِدًّا.»','“Onlar da derlerdi: Hayır, Bağdat çok uzak.”'),
('«فَكُنْتُ أَحْزَنُ، وَأَشْتَاقُ إِلَى أَهْلِي وَبَلَدِي.»','“Üzülür, aileme ve memleketime hasret çekerdim.”')]),
('الْبِضَاعَةُ الضَّائِعَةُ','Kayıp mallar',[
('«وَفِي يَوْمٍ وَصَلَتْ سَفِينَةٌ كَبِيرَةٌ إِلَى الْمِينَاءِ.»','“Bir gün limana büyük bir gemi geldi.”'),
('«نَزَلَ مِنْهَا التُّجَّارُ، وَأَخْرَجَ الْبَحَّارَةُ الْبَضَائِعَ.»','“Tüccarlar ondan indi, denizciler malları çıkardı.”'),
('«وَرَأَيْتُ صَنَادِيقَ عَلَيْهَا اسْمِي: السِّنْدِبَادُ!»','“Üzerinde adım yazan sandıklar gördüm: Sindbad!”'),
('«سَأَلْتُ الْقُبْطَانَ: لِمَنْ هَذِهِ الصَّنَادِيقُ؟»','“Kaptana sordum: Bu sandıklar kimin?”'),
('«قَالَ: لِتَاجِرٍ اسْمُهُ السِّنْدِبَادُ، غَرِقَ فِي الْبَحْرِ عِنْدَ جَزِيرَةِ الْحُوتِ.»','“Dedi ki: Balina adasının yanında denizde boğulan Sindbad adında bir tüccarın.”'),
('«قُلْتُ: أَنَا السِّنْدِبَادُ! لَمْ أَمُتْ!»','“Dedim ki: Sindbad benim! Ölmedim!”'),
('«نَظَرَ إِلَيَّ الْقُبْطَانُ طَوِيلًا، ثُمَّ عَرَفَنِي، وَفَرِحَ فَرَحًا شَدِيدًا.»','“Kaptan bana uzun uzun baktı, sonra tanıdı ve çok sevindi.”'),
('«وَقَالَ: الْحَمْدُ لِلّٰهِ عَلَى سَلَامَتِكَ، هَذِهِ بِضَاعَتُكَ كُلُّهَا.»','“Ve dedi ki: Selamete kavuştuğun için Allah’a hamd olsun; bu malların hepsi senin.”')]),
('الْعَوْدَةُ الْأُولَى','İlk dönüş',[
('«أَعْطَيْتُ الْمَلِكَ هَدِيَّةً جَمِيلَةً، فَأَعْطَانِي هَدَايَا أَكْثَرَ.»','“Krala güzel bir hediye verdim, o da bana daha çok hediye verdi.”'),
('«ثُمَّ رَكِبْتُ السَّفِينَةَ وَرَجَعْتُ إِلَى الْبَصْرَةِ، ثُمَّ إِلَى بَغْدَادَ.»','“Sonra gemiye binip Basra’ya, oradan da Bağdat’a döndüm.”'),
('«فَرِحَ أَهْلِي وَأَصْحَابِي بِرُجُوعِي.»','“Ailem ve arkadaşlarım dönüşüme sevindi.”'),
('«وَبِعْتُ الْبَضَائِعَ، وَصِرْتُ أَغْنَى مِنْ قَبْلُ.»','“Malları sattım ve eskisinden daha zengin oldum.”'),
('«وَتَصَدَّقْتُ عَلَى الْفُقَرَاءِ، وَشَكَرْتُ اللهَ.»','“Fakirlere sadaka verdim ve Allah’a şükrettim.”'),
('ثُمَّ أَعْطَى السِّنْدِبَادُ الْبَحْرِيُّ الْحَمَّالَ مِئَةَ دِينَارٍ، وَقَالَ: «تَعَالَ غَدًا، أَحْكِي لَكَ الرِّحْلَةَ الثَّانِيَةَ.»','Sonra Denizci Sindbad hamala yüz dinar verdi ve “Yarın gel, sana ikinci yolculuğu anlatayım” dedi.')]),
]
